'use strict';

// Review units for a change whose complete evidence exceeds one snapshot budget (design: chunked review).
//
// A unit is a VIEW of the combined snapshot, never a copy of its sources: `unitView` is a pure, read-only
// function that returns an ordinary snapshot an unchanged examiner, challenger and validator can use.
// `mergeUnitReports` turns the validated per-unit reports back into ONE ordinary report over the combined
// snapshot, so the existing `validateInspection`, `scoreReport`, `approvalHold` and `combine` derive the
// decision exactly once, from that merged input. Nothing here decides anything and nothing here is called yet.
//
// Unit input shape (pinned by the design's record, `partition.units[]`; the partition planner produces it):
//   {id: string, owned: [changed paths], context_ids: [source ids of the combined snapshot]}
// Every changed path is owned by exactly one unit (invariant I1). A source that is not a changed file's own
// base/head source and is not named in any unit's `context_ids` is shared context and goes to every unit.

const {GATES, digest, specifiersOf, resolveSpecifier, patchOf, JS_PATH} = require('./acceptance.cjs');
const {refresh} = require('./acceptance-sources.cjs');
const {validateInspection} = require('./acceptance-review.cjs');

const DEFAULTS = Object.freeze({cap: 900000, sharedCap: 100000, manifestCap: 60000, foreignShare: 0.2});
// Strictest first: a violated gate anywhere is violated, `inapplicable` only when every unit says so.
const STRICTNESS = Object.freeze(['violated', 'unresolved', 'satisfied', 'inapplicable']);
const DISPOSITION = Object.freeze(['missing', 'inspected', 'excluded']);

function refuse(code, message, extra = {}) {
  return Object.assign(new Error(`${message} (${code})`), {code, ...extra});
}

const size = sources => sources.reduce((total, source) => total + source.content.length, 0);
const fileSources = file => [file.base_source, file.head_source].filter(Boolean);

// I1: the specs are a disjoint cover of the changed paths and `unit` is one of them.
function checkPartition(snapshot, unit, units) {
  const ids = units.map(item => item.id);
  const owned = units.flatMap(item => item.owned);
  if (units.some(item => typeof item.id !== 'string' || !item.id || !Array.isArray(item.owned) || !Array.isArray(item.context_ids)) ||
      new Set(ids).size !== ids.length || !units.some(item => item.id === unit.id && digest(item) === digest(unit))) {
    throw refuse('partition_invalid', 'Unit specifications are malformed, repeated or do not contain this unit');
  }
  if (owned.length !== new Set(owned).size || owned.length !== snapshot.paths.length || !snapshot.paths.every(name => owned.includes(name))) {
    throw refuse('partition_invalid', 'Units must own every changed path exactly once');
  }
  if (units.some(item => item.context_ids.some(id => !Object.hasOwn(snapshot.sources, id)))) {
    throw refuse('partition_invalid', 'A unit names context that is not a source of the combined snapshot');
  }
}

// Header lines precede the first hunk; inside hunks a line starting with `++` or `--` is still an added or removed line.
const patchLines = patch => {
  const counts = {additions: 0, deletions: 0};
  const body = patch.split('\n'); const start = body.findIndex(line => line.startsWith('@@'));
  for (const line of start < 0 ? [] : body.slice(start + 1)) {
    if (line.startsWith('+')) counts.additions++;
    else if (line.startsWith('-')) counts.deletions++;
  }
  return counts;
};

// Every changed path with its status, line counts, evidence size, rename origin and owning unit: all units see
// the whole change, so a reviewer knows what lies outside the files it owns.
function manifestOf(snapshot, units) {
  const owner = new Map(units.flatMap(item => item.owned.map(name => [name, item.id])));
  return snapshot.files.map(file => {
    const sources = fileSources(file).map(id => snapshot.sources[id]);
    const previous = sources.find(source => source.path !== file.path)?.path;
    return {path: file.path, status: file.status, ...(previous ? {previous_path: previous} : {}), ...patchLines(patchOf(snapshot, file)),
      size: size(sources), unit: owner.get(file.path)};
  });
}

// For each import edge from an owned file to a changed file of ANOTHER unit, that callee's patch, read-only.
// Total size is bounded; what does not fit is listed so the omission is visible, never silent.
function foreignHunks(snapshot, ownedFiles, ownedPaths, units, budget) {
  const owner = new Map(units.flatMap(item => item.owned.map(name => [name, item.id])));
  const others = snapshot.files.filter(file => !ownedPaths.has(file.path));
  const known = others.map(file => file.path);
  const wanted = new Set();
  for (const file of ownedFiles.filter(item => item.head_source && JS_PATH.test(item.path))) {
    for (const specifier of specifiersOf(snapshot.sources[file.head_source].content)) {
      for (const target of resolveSpecifier(file.path, specifier, known)) wanted.add(target);
    }
  }
  const hunks = []; const omitted = [];
  let used = 0;
  for (const file of others.filter(item => wanted.has(item.path)).sort((a, b) => (a.path < b.path ? -1 : 1))) {
    // A file added whole stores only its patch header; the foreign unit does not hold its source, so the full patch is restored.
    const patch = patchOf(snapshot, file);
    if (used + patch.length > budget) omitted.push(file.path);
    else {used += patch.length; hunks.push({path: file.path, unit: owner.get(file.path), status: file.status, patch});}
  }
  return {foreign_hunks: hunks, foreign_omitted: omitted};
}

// A normal snapshot for one unit. Same base, head, policy and configuration as the combined snapshot, so its
// digest binds all of them; `partition_of` binds the combined snapshot itself.
function unitView(snapshot, unit, options = {}) {
  const {cap, sharedCap, manifestCap, foreignShare} = {...DEFAULTS, ...options};
  const units = options.units || [unit];
  checkPartition(snapshot, unit, units);
  const ownedPaths = new Set(unit.owned);
  const ownedFiles = snapshot.files.filter(file => ownedPaths.has(file.path));
  const changed = new Set(snapshot.files.flatMap(fileSources));
  const mine = new Set(ownedFiles.flatMap(fileSources));
  const named = new Set(units.flatMap(item => item.context_ids));
  const ids = Object.keys(snapshot.sources).filter(id => mine.has(id) || unit.context_ids.includes(id) ||
    snapshot.sources[id].authority === 'derived' || (!changed.has(id) && !named.has(id)));
  const shared = ids.filter(id => !mine.has(id) && !unit.context_ids.includes(id));
  if (size(shared.map(id => snapshot.sources[id])) > sharedCap) {
    throw refuse('shared_context_too_large', 'Shared review context exceeds its cap', {unit: unit.id});
  }
  const manifest = manifestOf(snapshot, units);
  if (JSON.stringify(manifest).length > manifestCap) throw refuse('manifest_too_large', 'The change manifest exceeds its cap', {unit: unit.id});
  const previousPaths = new Set(ownedFiles.flatMap(file => fileSources(file).map(id => snapshot.sources[id].path)));
  const first = units[0].id === unit.id;
  const view = {...snapshot,
    paths: [...unit.owned].sort(), files: ownedFiles,
    sources: Object.fromEntries(ids.map(id => [id, snapshot.sources[id]])),
    history: snapshot.history.filter(item => previousPaths.has(item.path)),
    // A prior finding belongs to the unit that owns its path; one whose path is no longer in the change goes to the first unit.
    prior_findings: snapshot.prior_findings?.filter(item => ownedPaths.has(item.path) || (first && !snapshot.paths.includes(item.path))),
    unit: {id: unit.id, owned: [...unit.owned].sort(), context_ids: [...unit.context_ids].sort()},
    partition_of: snapshot.digest, change_manifest: manifest,
    ...foreignHunks(snapshot, ownedFiles, ownedPaths, units, Math.floor(cap * foreignShare))};
  if (snapshot.covering_tests) view.covering_tests = Object.fromEntries(Object.entries(snapshot.covering_tests).filter(([name]) => ownedPaths.has(name)));
  delete view.digest;
  try {
    return refresh(view, cap);
  } catch (error) {
    throw refuse('unit_exceeds_budget', error.message, {unit: unit.id});
  }
}

// `reports`: [{view, report, drafts}] from running the unchanged reviewers on each `unitView`, in plan order.
// `snapshot`: the combined snapshot. Returns {report, drafts} for the existing validators.
function mergeUnitReports(reports, snapshot) {
  const views = reports.map(item => item.view);
  const ids = views.map(view => view.unit.id);
  const owned = views.flatMap(view => view.unit.owned);
  if (new Set(ids).size !== ids.length || owned.length !== new Set(owned).size || owned.length !== snapshot.paths.length ||
      !snapshot.paths.every(name => owned.includes(name))) {
    throw refuse('merge_invalid', 'Unit reports must cover every changed path exactly once');
  }
  for (const {view, report, drafts = []} of reports) {
    if (view.partition_of !== snapshot.digest || view.digest !== refresh(structuredClone(view), Infinity).digest) {
      throw refuse('merge_invalid', 'A unit report belongs to another snapshot or an altered view', {unit: view.unit.id});
    }
    validateInspection(report, view, drafts);
  }
  const ledger = new Set((snapshot.prior_findings || []).map(item => item.id));
  const namespaced = (unit, name) => `${unit}:${name}`;
  const findingId = item => (ledger.has(item.id) ? item.id : `p${digest(item.path).slice(0, 8)}:${item.id}`);
  // Rewrites every evidence reference of a report fragment to its namespaced form.
  const refs = (value, rename) => {
    if (Array.isArray(value)) return value.map(item => refs(item, rename));
    if (!value || typeof value !== 'object') return value;
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key,
      key === 'evidence' && Array.isArray(item) && item.every(entry => typeof entry === 'string') ? item.map(rename) : refs(item, rename)]));
  };
  const merged = {evidence: [], units: [], findings: [], accounting: [], resolutions: [], reopenings: [], summaries: []};
  const drafted = [];
  const gates = new Map(GATES.map(name => [name, []]));
  const dispositions = new Map(Object.keys(snapshot.sources).map(id => [id, []]));
  const dependencies = new Map();
  const ownerOf = new Map(snapshot.files.flatMap(file => {
    const unit = views.find(view => view.unit.owned.includes(file.path)).unit.id;
    return fileSources(file).map(id => [id, unit]);
  }));
  for (const {view, report, drafts = []} of reports) {
    const unit = view.unit.id;
    const rename = id => namespaced(unit, id);
    const draftIds = new Map(drafts.flatMap(draft => draft.findings.map(item => [item.id, findingId(item)])));
    merged.evidence.push(...report.evidence.map(item => ({...item, id: rename(item.id)})));
    merged.units.push(...refs(report.units, rename).map(item => ({...item, id: namespaced(unit, item.id)})));
    for (const item of refs(report.findings, rename)) {
      const id = findingId(item);
      if (merged.findings.some(other => other.id === id)) throw refuse('merge_invalid', 'Two units report the same finding identity', {unit});
      merged.findings.push({...item, id});
    }
    merged.accounting.push(...refs(report.accounting, rename).map(item => ({...item, units: item.units.map(id => namespaced(unit, id))})));
    merged.resolutions.push(...refs(report.resolutions, rename).map(item => ({...item, id: draftIds.get(item.id) || item.id})));
    merged.summaries.push(`${unit}: ${report.summary}`);
    for (const gate of report.gates) gates.get(gate.name).push({unit, gate: refs(gate, rename)});
    drafts.forEach((draft, index) => {
      const key = id => namespaced(unit, `d${index}:${id}`);
      drafted[index] = drafted[index] || {findings: [], evidence: []};
      drafted[index].evidence.push(...draft.evidence.map(item => ({...item, id: key(item.id)})));
      drafted[index].findings.push(...refs(draft.findings, key).map(item => ({...item, id: findingId(item)})));
    });
    if (snapshot.review_manifest_version) {
      merged.reopenings.push(...refs(report.reopenings, rename));
      for (const item of report.coverage.sources) dispositions.get(item.source).push({unit, item: refs(item, rename)});
      for (const item of report.coverage.dependencies) {
        dependencies.set(item.path, [...(dependencies.get(item.path) || []), {unit, item: refs(item, rename)}]);
      }
    }
  }
  const report = {version: 4, snapshot: snapshot.digest, summary: merged.summaries.join(' | ').slice(0, 2000), evidence: merged.evidence,
    units: merged.units, findings: merged.findings,
    gates: GATES.map(name => {
      const state = STRICTNESS.find(candidate => gates.get(name).some(({gate}) => gate.state === candidate));
      const {unit, gate} = gates.get(name).find(item => item.gate.state === state);
      return {...gate, reason: `${unit}: ${gate.reason}`.slice(0, 2000)};
    }),
    accounting: merged.accounting, resolutions: merged.resolutions};
  if (snapshot.review_manifest_version) {
    // `missing` anywhere stays missing; otherwise the owner unit's judgement of a source stands.
    const choose = (entries, owner) => {
      const rank = entry => DISPOSITION.indexOf(entry.item.state);
      const best = [...entries].sort((a, b) => rank(a) - rank(b));
      return (rank(best[0]) > 0 && entries.find(entry => entry.unit === owner)) || best[0];
    };
    report.coverage = {
      sources: [...dispositions].map(([source, entries]) => {
        if (!entries.length) return {source, state: 'missing', reason: 'No review unit was given this source.', evidence: []};
        const {unit, item} = choose(entries, ownerOf.get(source));
        return {...item, reason: `${unit}: ${item.reason}`.slice(0, 2000)};
      }),
      dependencies: [...dependencies.values()].map(entries => {
        const {unit, item} = choose(entries);
        return {...item, reason: `${unit}: ${item.reason}`.slice(0, 2000)};
      }),
    };
    report.reopenings = merged.reopenings;
    // Missing material evidence is by rule an unresolved completeness gate (acceptance.cjs validateCompleteness).
    const completeness = report.gates.find(gate => gate.name === 'review_completeness');
    if (completeness.state !== 'unresolved' && [...report.coverage.sources, ...report.coverage.dependencies].some(item => item.state === 'missing')) {
      completeness.state = 'unresolved'; completeness.reason = `${completeness.reason} (Material evidence is recorded as missing.)`.slice(0, 2000);
    }
  }
  return {report, drafts: drafted};
}

module.exports = {DEFAULTS, unitView, mergeUnitReports};

'use strict';

// Unit views and report merge. The unit specs below are a LOCAL fixture of the design's pinned shape
// {id, owned, context_ids}; the real partition planner is a separate module and is not used here.

const {test} = require('node:test');
const assert = require('node:assert/strict');
const {digest, GATES, scoreReport, validateReport, validateApproval, approvalHold} = require('./acceptance.cjs');
const {refresh} = require('./acceptance-sources.cjs');
const {template, validateInspection, combine} = require('./acceptance-review.cjs');
const {withDiscovery} = require('./acceptance-controller.cjs');
const {unitView, mergeUnitReports, DEFAULTS} = require('./review-units.cjs');

const HEAD = 'a'.repeat(40), BASE = 'b'.repeat(40);
const lines = n => Array.from({length: n}, (_, i) => `line ${i + 1}`).join('\n');
const patch = '--- a/f\n+++ b/f\n@@ -1,2 +1,3 @@\n context\n-old\n+new\n+newer\n';
const source = (path, content, extra = {}) => ({path, ref: HEAD, authority: 'untrusted', kind: 'source', content, ...extra});

// Eight changed files: a lockfile with a derived summary, a rename, a removal, an addition, tests and docs.
function combined({prior = [], manifest = true} = {}) {
  const sources = {
    contract: {path: '.github/clouseau.md', ref: BASE, authority: 'trusted', kind: 'contract', content: '# Contract\nKeep behaviour.\n'},
    verification: {path: 'verification', ref: HEAD, authority: 'trusted', kind: 'verification', content: '{"ok":true}'},
    'local-request': {path: 'local-request', ref: 'r', authority: 'untrusted', kind: 'requirement', content: 'Change the modules.'},
    'a.head': source('src/a.cjs', "const b = require('./b.cjs');\nmodule.exports = () => b();\n"),
    'a.base': source('src/a.cjs', 'module.exports = () => 1;\n', {ref: BASE}),
    'at.head': source('src/a.test.cjs', "const a = require('./a.cjs');\nawait a();\n"),
    'b.head': source('src/b.cjs', 'module.exports = () => 2;\n'),
    'bt.head': source('src/b.test.cjs', "const b = require('./b.cjs');\nb();\n"),
    'gone.base': source('src/gone.cjs', 'exports.x = 1;\n', {ref: BASE}),
    'old.base': source('src/old-name.cjs', 'exports.y = 1;\n', {ref: BASE}),
    'new.head': source('src/new-name.cjs', 'exports.y = 1;\n// moved\n'),
    'docs.head': source('docs/readme.md', '# Docs\nText.\n'),
    'docs.base': source('docs/readme.md', '# Docs\n', {ref: BASE}),
    'lock.base': source('pnpm-lock.yaml', 'Dependency summary (base)\n', {ref: BASE, authority: 'derived', kind: 'lockfile-summary'}),
    'lock.head': source('pnpm-lock.yaml', 'Dependency summary (head)\n', {authority: 'derived', kind: 'lockfile-summary'}),
    'ctx.engine': source('.clouseau-ci/engine.cjs', 'engine context\n'),
  };
  const files = [
    {path: 'src/a.cjs', status: 'modified', patch, base_source: 'a.base', head_source: 'a.head'},
    {path: 'src/a.test.cjs', status: 'added', patch, head_source: 'at.head'},
    {path: 'src/b.cjs', status: 'added', patch: '--- /dev/null\n+++ b/src/b.cjs\n@@ -0,0 +1,2 @@\n+only\n+++counted\n', head_source: 'b.head'},
    {path: 'src/b.test.cjs', status: 'added', patch, head_source: 'bt.head'},
    {path: 'src/gone.cjs', status: 'removed', patch: '-x\n', base_source: 'gone.base'},
    {path: 'src/new-name.cjs', status: 'renamed', patch, base_source: 'old.base', head_source: 'new.head'},
    {path: 'docs/readme.md', status: 'modified', patch, base_source: 'docs.base', head_source: 'docs.head'},
    {path: 'pnpm-lock.yaml', status: 'modified', patch: '# replaced\n', base_source: 'lock.base', head_source: 'lock.head'},
  ];
  const snapshot = {version: 2, ...(manifest ? {review_manifest_version: 1} : {}), repository: 'o/r', number: 0, base_sha: BASE, head_sha: HEAD,
    head_repository: {owner: 'o', repo: 'r'}, paths: files.map(file => file.path).sort(), config_digest: 'c', policy_digest: 'p',
    sources, files, history: [{path: 'src/a.cjs', commits: 'x'}, {path: 'src/old-name.cjs', commits: 'y'}, {path: 'docs/readme.md', commits: 'z'}],
    tickets: [], intent_confirmation: null, prior_findings: prior, claims: {title: 'change', description: 'Describe the change.'},
    covering_tests: {'src/a.cjs': ['src/a.test.cjs'], 'src/b.cjs': ['src/b.test.cjs']}};
  return refresh(snapshot, 3000000);
}
const U0 = {id: 'u0', owned: ['src/a.cjs', 'src/a.test.cjs', 'docs/readme.md', 'pnpm-lock.yaml'], context_ids: []};
const U1 = {id: 'u1', owned: ['src/b.cjs', 'src/b.test.cjs', 'src/gone.cjs', 'src/new-name.cjs'], context_ids: ['ctx.engine']};
const UNITS = [U0, U1];

const views = snapshot => UNITS.map(unit => unitView(snapshot, unit, {units: UNITS}));

// A valid, fully satisfied report for a view, optionally with edits; built from the controller's own template.
function report(view, edit = () => {}) {
  const value = template(view);
  for (const item of value.evidence) item.quote = view.sources[item.source].content.split('\n')[item.start - 1];
  for (const unit of value.units) unit.paths = value.accounting.filter(item => item.units.includes(unit.id)).map(item => item.path);
  for (const gate of value.gates) gate.state = 'satisfied';
  edit(value, view);
  return value;
}
function evidenceFor(value, view, filename) {
  return value.evidence.find(item => view.sources[item.source].path === filename).id;
}
const factors = (value, level, evidence) => Object.fromEntries(['necessity', 'confidence', 'severity', 'activation', 'irreversibility', 'reach', 'detection', 'propagation', 'recurrence']
  .map(name => [name, {value: name === 'confidence' ? level : 1, evidence: [evidence], reason: 'Observed.'}]));
function addFinding(value, view, filename, id, level) {
  const evidence = evidenceFor(value, view, filename);
  value.findings.push({id, title: 'Defect', path: filename, cause: `cause ${id}`, trigger: 't', consequence: 'c', obligation: 'o', evidence: [evidence],
    factors: factors(value, level, evidence), blast_radius: 1, opportunity: {mechanical: false, beneficial: false, within_scope: false, verified: false},
    repair_paths: [filename]});
}
const merge = (snapshot, edits = [], drafts = []) => mergeUnitReports(views(snapshot).map((view, index) =>
  ({view, report: report(view, edits[index]), drafts: drafts[index]})), snapshot);

test('a view is an ordinary snapshot over the owned files with the shared context', () => {
  const snapshot = combined();
  const [v0, v1] = views(snapshot);
  assert.deepEqual(v0.paths, [...U0.owned].sort());
  assert.deepEqual(v0.files.map(file => file.path), ['src/a.cjs', 'src/a.test.cjs', 'docs/readme.md', 'pnpm-lock.yaml']);
  assert.equal(v0.base_sha, BASE); assert.equal(v0.config_digest, 'c'); assert.equal(v0.claims.description, 'Describe the change.');
  assert.equal(v0.partition_of, snapshot.digest);
  assert.notEqual(v0.digest, v1.digest);
  assert.equal(v0.digest, refresh(structuredClone(v0)).digest, 'the digest is the existing refresh digest');
  // shared: contract, verification, request and BOTH derived lockfile summaries; the engine context only in the unit that names it
  for (const id of ['contract', 'verification', 'local-request', 'lock.base', 'lock.head']) assert.ok(v0.sources[id] && v1.sources[id], id);
  assert.ok(!v0.sources['ctx.engine'] && v1.sources['ctx.engine']);
  assert.ok(!v0.sources['b.head'] && v1.sources['b.head'], 'a changed source belongs to its owner only');
  assert.deepEqual(v1.history, [{path: 'src/old-name.cjs', commits: 'y'}], 'history of a rename is kept under its old path');
  assert.deepEqual(v0.covering_tests, {'src/a.cjs': ['src/a.test.cjs']});
  assert.deepEqual(v1.covering_tests, {'src/b.cjs': ['src/b.test.cjs']});
  // the unit input is not mutated and the combined snapshot is untouched
  assert.equal(snapshot.digest, refresh(structuredClone(snapshot), 3000000).digest);
  // and an unchanged validator accepts a report over it
  validateInspection(report(v0), v0);
  validateInspection(report(v1), v1);
});

test('the manifest lists the whole change with owners, counts, sizes and rename origins', () => {
  const [v0, v1] = views(combined());
  assert.deepEqual(v0.change_manifest, v1.change_manifest);
  const entry = name => v0.change_manifest.find(item => item.path === name);
  assert.deepEqual(entry('src/a.cjs'), {path: 'src/a.cjs', status: 'modified', additions: 2, deletions: 1,
    size: 'module.exports = () => 1;\n'.length + "const b = require('./b.cjs');\nmodule.exports = () => b();\n".length, unit: 'u0'});
  assert.deepEqual(entry('src/b.cjs'), {path: 'src/b.cjs', status: 'added', additions: 2, deletions: 0, size: 'module.exports = () => 2;\n'.length, unit: 'u1'});
  assert.equal(entry('src/new-name.cjs').previous_path, 'src/old-name.cjs');
  assert.equal(entry('src/gone.cjs').status, 'removed');
  assert.equal(v0.change_manifest.length, 8);
});

test('imports of a changed file in another unit bring that callee hunk, read-only and bounded', () => {
  const snapshot = combined();
  const [v0, v1] = views(snapshot);
  assert.deepEqual(v0.foreign_hunks, [{path: 'src/b.cjs', unit: 'u1', status: 'added', patch: '--- /dev/null\n+++ b/src/b.cjs\n@@ -0,0 +1,2 @@\n+only\n+++counted\n'}]);
  assert.deepEqual(v0.foreign_omitted, []);
  assert.deepEqual(v1.foreign_hunks, [], 'b.test imports b (owned); nothing foreign');
  assert.ok(!v0.sources['b.head'], 'a foreign hunk is not citable evidence');
});

test('a file added whole (patch_body head_source) is read through patchOf: counts and foreign hunks are the full patch, owned form stays stored', () => {
  const snapshot = combined();
  const file = snapshot.files.find(item => item.path === 'src/b.cjs');
  Object.assign(file, {patch: '--- /dev/null\n+++ b/src/b.cjs\n@@ -0,0 +1 @@\n', patch_body: 'head_source'}); refresh(snapshot, 3000000);
  const [v0, v1] = views(snapshot);
  const full = '--- /dev/null\n+++ b/src/b.cjs\n@@ -0,0 +1 @@\n+module.exports = () => 2;\n';
  assert.deepEqual(v0.foreign_hunks, [{path: 'src/b.cjs', unit: 'u1', status: 'added', patch: full}]);
  assert.equal(v0.change_manifest.find(item => item.path === 'src/b.cjs').additions, 1, 'the body is counted, not just the header');
  assert.equal(v1.files.find(item => item.path === 'src/b.cjs').patch_body, 'head_source', 'the owner keeps the stored form');
  assert.equal(v1.files.find(item => item.path === 'src/b.cjs').patch.length, file.patch.length);
  const tight = unitView(snapshot, U0, {units: UNITS, cap: 60000, foreignShare: full.length / 60000 / 2});
  assert.deepEqual(tight.foreign_omitted, ['src/b.cjs'], 'sized on the restored patch');
  validateInspection(report(v1), v1);
  const {report: merged} = merge(snapshot);
  validateInspection(merged, snapshot);
});

test('a view over the cap, or with oversized shared context or manifest, is refused with a typed code', () => {
  const snapshot = combined();
  assert.throws(() => unitView(snapshot, U0, {units: UNITS, cap: 1000}), error => error.code === 'unit_exceeds_budget' && error.unit === 'u0' && /source budget/.test(error.message));
  assert.throws(() => unitView(snapshot, U0, {units: UNITS, sharedCap: 10}), error => error.code === 'shared_context_too_large');
  assert.throws(() => unitView(snapshot, U0, {units: UNITS, manifestCap: 100}), error => error.code === 'manifest_too_large');
  const tight = unitView(snapshot, U0, {units: UNITS, cap: 60000, foreignShare: 0.0001});
  assert.deepEqual(tight.foreign_hunks, []);
  assert.deepEqual(tight.foreign_omitted, ['src/b.cjs'], 'what does not fit is listed, never silently dropped');
});

test('the specs must be a disjoint cover of the changed paths and contain the unit', () => {
  const snapshot = combined();
  const bad = (unit, units) => assert.throws(() => unitView(snapshot, unit, {units}), error => error.code === 'partition_invalid');
  bad(U0, [U0]);
  bad(U0, [U0, {...U1, owned: [...U1.owned, 'src/a.cjs']}]);
  bad(U0, [U0, {...U1, owned: U1.owned.slice(1)}]);
  bad(U0, [U0, {...U1, id: 'u0'}]);
  bad(U0, [U1]);
  bad({...U0, id: ''}, [{...U0, id: ''}, U1]);
  bad(U0, [U0, {...U1, context_ids: ['missing']}]);
  bad(U0, [U0, {...U1, owned: 'x'}]);
  bad(U0, [U0, {id: 'u1', owned: U1.owned}]);
  bad({...U0, owned: [...U0.owned]}, [{...U0, context_ids: ['contract']}, U1]);
});

test('a change reviewed as one unit needs no unit list', () => {
  const snapshot = combined();
  const whole = {id: 'u0', owned: [...snapshot.paths], context_ids: []};
  const view = unitView(snapshot, whole);
  assert.deepEqual(view.paths, snapshot.paths);
  assert.deepEqual(view.foreign_hunks, []);
  assert.equal(view.prior_findings.length, 0);
